Here’s a simple Rust example that reads a file line by line and counts the lines:

```rust
use std::fs::File;
use std::io::{self, BufRead};

fn main() -> io::Result<()> {
    let file = File::open("example.txt")?;
    let reader = io::BufReader::new(file);

    let mut count = 0;

    for line in reader.lines() {
        let _line = line?;
        count += 1;
    }

    println!("Line count: {count}");

    Ok(())
}
